#!/usr/bin/env python3
from pathlib import Path
import sys
ROOT=Path(sys.argv[1] if len(sys.argv)>1 else '.')
def r(p): return (ROOT/p).read_text()
def w(p,s): (ROOT/p).write_text(s)
def rep(p,a,b,count=1):
    s=r(p)
    if a not in s: raise SystemExit(f'v200 autopilot missing anchor {p}: {a[:180]!r}')
    w(p,s.replace(a,b,count))

# -----------------------------------------------------------------------------
# Pure eligibility rules so automatic YouTube publication can never silently
# bypass the user's safety configuration.
# -----------------------------------------------------------------------------
w('src/youtubeAutopilotCore.ts',r'''import type {Channel,Settings,VideoJob} from './types';
export type YoutubeAutopilotEligibility={ok:boolean;reasons:string[]};
export function youtubeAutopilotEligibility(channel:Channel,job:VideoJob,settings:Settings,uploadsLast24h:number,duplicate=false,hasRecovery=false):YoutubeAutopilotEligibility{const reasons:string[]=[];if(!settings.autoUploadYoutube)reasons.push('AUTO_UPLOAD_OFF');if(!settings.youtubePublishSafeMode)reasons.push('SAFE_MODE_REQUIRED');if(!channel.youtubeProfileId)reasons.push('OAUTH_REQUIRED');if(!channel.safeDailyUploadLimit||channel.safeDailyUploadLimit<1)reasons.push('SAFE_DAILY_LIMIT_REQUIRED');if(channel.safeDailyUploadLimit&&uploadsLast24h>=channel.safeDailyUploadLimit)reasons.push('SAFE_DAILY_LIMIT_REACHED');if(job.status!=='READY_UPLOAD'&&!hasRecovery)reasons.push('VIDEO_NOT_READY');if(!job.finalPath)reasons.push('VIDEO_FILE_REQUIRED');if(!job.title?.trim())reasons.push('TITLE_REQUIRED');if(!job.publishAt)reasons.push('SCHEDULE_REQUIRED');if(duplicate)reasons.push('DUPLICATE');return{ok:reasons.length===0,reasons}}
''')
w('src/youtubeAutopilotCore.test.ts',r'''import {describe,it,expect} from 'vitest';import {youtubeAutopilotEligibility} from './youtubeAutopilotCore';
const settings:any={autoUploadYoutube:true,youtubePublishSafeMode:true};const channel:any={youtubeProfileId:'p',safeDailyUploadLimit:15};const job:any={status:'READY_UPLOAD',finalPath:'/x.mp4',title:'Title',publishAt:'2026-09-10T10:00:00Z'};
describe('YouTube autopilot safety',()=>{it('requires explicit safe limit and safe mode',()=>{expect(youtubeAutopilotEligibility({...channel,safeDailyUploadLimit:undefined},job,settings,0).ok).toBe(false);expect(youtubeAutopilotEligibility(channel,job,{...settings,youtubePublishSafeMode:false},0).ok).toBe(false)});it('blocks duplicate and full rolling limit',()=>{expect(youtubeAutopilotEligibility(channel,job,settings,15).reasons).toContain('SAFE_DAILY_LIMIT_REACHED');expect(youtubeAutopilotEligibility(channel,job,settings,0,true).reasons).toContain('DUPLICATE')});it('allows a fully prepared job',()=>expect(youtubeAutopilotEligibility(channel,job,settings,0).ok).toBe(true))});
''')

# -----------------------------------------------------------------------------
# Real optional YouTube Autopilot. One video per channel per cycle. It resumes a
# persisted session before considering a new videos.insert.
# -----------------------------------------------------------------------------
w('src/youtubeAutopilot.ts',r'''import {api} from './api';import {useApp} from './store';import type {AutopilotSummary,Channel,VideoJob} from './types';import {youtubeAutopilotEligibility} from './youtubeAutopilotCore';import {acquireChannelUploadLock,beginPublishAttempt,completePublishAttempt,completeStartedPublishAttempt,findSuccessfulUpload,isYoutubeDailyUploadLimitError,releaseChannelUploadLock,safeDailyStatus} from './youtubePublishSafety';import {planYoutubeQuota,releaseYoutubeQuotaReservation,reserveYoutubeQuota} from './youtubeQuota';import {humanizeError} from './errorCenter';
const n=(j:VideoJob)=>`VIDEO_${String(j.number).padStart(3,'0')}`;
async function finishResumed(channel:Channel,job:VideoJob,summary:AutopilotSummary){const uploaded=await api.youtubeResumeUpload(job.id);if(!uploaded.videoId)throw new Error('UPLOAD_NEEDS_VERIFICATION: YouTube video ID отсутствует');completeStartedPublishAttempt(job.id,uploaded.videoId);let thumbError='';if(job.thumbnailPath&&channel.youtubeProfileId){const op=`autopilot-resume-thumb:${job.id}:${Date.now()}`,plan=planYoutubeQuota([{method:'thumbnails.set',count:1}]);if(plan.affordable&&reserveYoutubeQuota(op,plan)){try{await api.youtubeSetThumbnail(channel.youtubeProfileId,uploaded.videoId,job.thumbnailPath,op)}catch(e){thumbError=humanizeError(e,'thumbnail').message}finally{releaseYoutubeQuotaReservation(op)}}}useApp.getState().patchJob(job.id,{status:'SCHEDULED',youtubeVideoId:uploaded.videoId,uploadedAt:new Date().toISOString(),uploadProgress:100,uploadInterruptedAt:undefined,error:thumbError||undefined});useApp.getState().updateChannel(channel.id,{lastUploadAt:new Date().toISOString(),knownUploadLimitState:'ok',lastDailyLimitError:undefined});summary.uploads++;summary.notes.push(`${channel.name}: ${n(job)} — YouTube recovery завершён`)}
export async function runYoutubeAutopilotForChannel(channel:Channel,summary:AutopilotSummary){const state=useApp.getState(),s=state.settings;if(!s.autoUploadYoutube||!s.youtubePublishSafeMode||!channel.youtubeProfileId||!channel.safeDailyUploadLimit)return;const sessions=await api.youtubeUploadSessions().catch(()=>[]),jobs=useApp.getState().jobs.filter(j=>j.channelId===channel.id).sort((a,b)=>a.number-b.number),recover=sessions.find(x=>jobs.some(j=>j.id===x.jobId));if(recover){const job=jobs.find(j=>j.id===recover.jobId);if(!job)return;const token=acquireChannelUploadLock(channel.id);if(!token)return;try{await finishResumed(channel,job,summary)}catch(e){const h=humanizeError(e,'upload');useApp.getState().patchJob(job.id,{status:'ERROR',error:h.message,uploadInterruptedAt:new Date().toISOString()});summary.errors++;summary.notes.push(`${channel.name}: ${h.message}`)}finally{releaseChannelUploadLock(channel.id,token)}return}
 const job=jobs.find(j=>j.status==='READY_UPLOAD'&&j.finalPath);if(!job)return;let fp;try{fp=await api.youtubeFileFingerprint(job.finalPath!)}catch(e){const h=humanizeError(e,'upload');summary.errors++;summary.notes.push(`${channel.name}: ${h.message}`);return}const duplicate=Boolean(findSuccessfulUpload(channel.id,fp.fingerprint)),daily=safeDailyStatus(channel.id,channel.safeDailyUploadLimit),eligibility=youtubeAutopilotEligibility(channel,job,s,daily.used,duplicate,false);if(!eligibility.ok)return;const thumb=Boolean(job.thumbnailPath),plan=planYoutubeQuota([{method:'videos.insert',count:1,label:'Autopilot video upload'},...(thumb?[{method:'thumbnails.set' as const,count:1,label:'Autopilot thumbnail'}]:[])]);if(!plan.affordable){summary.notes.push(`${channel.name}: автопубликация ждёт quota`);return}const token=acquireChannelUploadLock(channel.id);if(!token)return;const operationId=`autopilot-publish:${channel.id}:${job.id}:${Date.now()}`;if(!reserveYoutubeQuota(operationId,plan)){releaseChannelUploadLock(channel.id,token);return}const attempt=beginPublishAttempt({channelId:channel.id,jobId:job.id,filePath:job.finalPath!,fingerprint:fp.fingerprint,fileSize:fp.size});useApp.getState().patchJob(job.id,{status:'UPLOADING',uploadProgress:0,error:undefined,uploadFingerprint:fp.fingerprint});try{const uploaded=await api.youtubeUpload(channel.youtubeProfileId,job.id,job.finalPath!,job.title,job.description,job.tags,job.publishAt,s.youtubeCategoryId,operationId);if(!uploaded.videoId)throw new Error('YouTube не вернул video ID');completePublishAttempt(attempt.id,uploaded.videoId);let thumbError='';if(job.thumbnailPath){try{await api.youtubeSetThumbnail(channel.youtubeProfileId,uploaded.videoId,job.thumbnailPath,operationId)}catch(e){thumbError=humanizeError(e,'thumbnail').message}}useApp.getState().patchJob(job.id,{status:'SCHEDULED',youtubeVideoId:uploaded.videoId,uploadedAt:new Date().toISOString(),uploadProgress:100,error:thumbError||undefined});useApp.getState().updateChannel(channel.id,{lastUploadAt:new Date().toISOString(),knownUploadLimitState:'ok',lastDailyLimitError:undefined});summary.uploads++;summary.notes.push(`${channel.name}: ${n(job)} автоматически загружено на YouTube`);useApp.getState().log(`${n(job)} автоматически загружено на YouTube${thumbError?' • thumbnail требует внимания':''}`)}catch(e){const fresh=await api.youtubeUploadSessions().catch(()=>[]);if(fresh.some(x=>x.jobId===job.id)){const h=humanizeError(e,'upload');useApp.getState().patchJob(job.id,{status:'ERROR',error:h.message,uploadInterruptedAt:new Date().toISOString()});summary.notes.push(`${channel.name}: ${n(job)} — загрузка сохранена для recovery`);return}const h=humanizeError(e,'upload');useApp.getState().patchJob(job.id,{status:'ERROR',error:h.message});if(isYoutubeDailyUploadLimitError(e))useApp.getState().updateChannel(channel.id,{knownUploadLimitState:'limited',lastDailyLimitError:h.message,lastUploadAt:new Date().toISOString()});summary.errors++;summary.notes.push(`${channel.name}: ${h.message}`)}finally{releaseYoutubeQuotaReservation(operationId);releaseChannelUploadLock(channel.id,token)}}
''')

