s=s.replace("function logError(summary:AutopilotSummary,label:string,e:unknown){summary.errors++;const msg=`${label}: ${String(e)}`;summary.notes.push(msg);useApp.getState().log(msg,'error')}", "function logError(summary:AutopilotSummary,label:string,e:unknown){summary.errors++;const h=humanizeError(e,label.toLocaleLowerCase('ru-RU').includes('endlume')?'endlume':'storage');const msg=`${label}: ${h.message}`;summary.notes.push(msg);useApp.getState().log(msg,'error')}")
anchor="""    for(const channel of useApp.getState().channels.filter(c=>c.enabled)){try{await processChannel(channel,summary,aiBudget)}catch(e){logError(summary,`${channel.name}: цикл`,e)}}
    const moved=summary.tracksMoved+summary.imagesMoved+summary.renderQueued+summary.metadataGenerated+summary.prepared;"""
replacement="""    for(const channel of useApp.getState().channels.filter(c=>c.enabled)){try{await processChannel(channel,summary,aiBudget);if(useApp.getState().settings.autoUploadYoutube)await runYoutubeAutopilotForChannel(channel,summary)}catch(e){logError(summary,`${channel.name}: цикл`,e)}}
    const moved=summary.tracksMoved+summary.imagesMoved+summary.renderQueued+summary.metadataGenerated+summary.prepared+summary.uploads;"""
